use nepl3_core::budget::{Budget,Limits,StopReason};
use nepl3_markup::html::*;
fn b()->Budget {Budget::new(Limits{work:100_000_000,allocation_units:200_000_000,nodes:2_000_000,depth:200_000,output_bytes:10_000_000,..Limits::default()})}
fn e(tag:HtmlTag,children:Vec<u64>)->HtmlNode {HtmlNode::Element{tag,children,attributes:vec![]}}
fn text(t:&str)->HtmlNode {HtmlNode::Text{text:t.into()}}
#[test]
fn independent_serializer_frontier(){
 let p=HtmlPolicy{classes:vec![]};
 for n in [1,1000,100000] {
  let f=HtmlFragment{root:0,nodes:vec![e(HtmlTag::Div,vec![1;n]),text("x")]};
  let proof=validate(&f,HtmlSlot::Block,&p,&mut b()).unwrap();
  let mut q=Budget::new(Limits{work:6,..b().limits()});
  let result=serialize(&proof,&mut q);
  println!("FRONTIER n={n} result={result:?} usage={:?}",q.usage());
  assert_eq!(result,Err(HtmlError::Stopped(StopReason::WorkLimit)));
 }
}
