use nepl3_core::{budget::{Budget,Limits},schema::SchemaRegistry,source::{SourceAdmission,SourceStore},value::NdfValue};
use nepl3_markup::{html::*,portable};
use nepl3_wire::foundation::FoundationCodec;
fn b()->Budget {Budget::new(Limits{work:100_000_000,allocation_units:100_000_000,nodes:2_000_000,depth:200_000,output_bytes:10_000_000,..Limits::default()})}
fn e(tag:HtmlTag,children:Vec<u64>,attributes:Vec<HtmlAttribute>)->HtmlNode {HtmlNode::Element{tag,children,attributes}}
fn t(s:&str)->HtmlNode {HtmlNode::Text{text:s.into()}}
fn registry()->SchemaRegistry {let mut r=SchemaRegistry::default();for d in [nepl3_core::schema::foundation::descriptor(&mut b()).unwrap(),nepl3_markup::schema::descriptor(&mut b()).unwrap()]{r.register(d.reference(&mut b()).unwrap(),d,&mut b()).unwrap();}r.finalize(&mut b()).unwrap();r}
fn req(nodes:Vec<HtmlNode>)->HtmlRequest {HtmlRequest{fragment:HtmlFragment{root:0,nodes},slot:HtmlSlot::Block,policy:HtmlPolicy{classes:vec!["known".into()]}}}
fn transfer(value:&NdfValue,r:&SchemaRegistry)->Result<HtmlRequest,String> {let bytes=nepl3_wire::encode(value,&mut b()).unwrap();let decoded=nepl3_wire::decode(&bytes,&mut b()).unwrap();let store=SourceStore::default();let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(r,&store,&mut admission).unwrap();portable::from_value(&decoded,r,&mut c,&mut b()).map_err(|e|format!("{e:?}"))}
fn encode(q:&HtmlRequest,r:&SchemaRegistry)->NdfValue {let store=SourceStore::default();let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(r,&store,&mut admission).unwrap();portable::to_value(q,r,&mut c,&mut b()).unwrap()}
#[test]
fn independently_bound_first_receiver_and_schema_valid_policy_changes(){
 use HtmlTag::*;
 let r=registry();let q=req(vec![e(Div,vec![1,2,4],vec![HtmlAttribute::Class{values:vec!["known".into()]}]),e(Img,vec![],vec![HtmlAttribute::Src{path:"assets/a.png".into()},HtmlAttribute::Alt{value:"\n<&\"\r\t".into()},HtmlAttribute::Width{value:4},HtmlAttribute::Height{value:5}]),e(A,vec![3],vec![HtmlAttribute::Href{value:HtmlHref::Fragment{id:"anchor".into()}}]),t("link"),e(Span,vec![5],vec![HtmlAttribute::Id{value:"anchor".into()},HtmlAttribute::Lang{value:"ja-Latn".into()},HtmlAttribute::DataId{value:"source".into()},HtmlAttribute::Role{value:HtmlRole::Note},HtmlAttribute::AriaLabel{value:"<&\r\n".into()}]),t("あ🙂\n\r")]);
 let raw=encode(&q,&r);let received=transfer(&raw,&r).unwrap();assert_eq!(q,received);
 let native=serialize(&validate(&q.fragment,q.slot,&q.policy,&mut b()).unwrap(),&mut b()).unwrap();
 let wire=serialize(&validate(&received.fragment,received.slot,&received.policy,&mut b()).unwrap(),&mut b()).unwrap();assert_eq!(native,wire);assert_eq!(encode(&received,&r),raw);
 for mode in 0..3 {
  let mut changed=raw.clone();let NdfValue::Record(request)=&mut changed else {panic!()};
  if mode==0 {let NdfValue::Record(policy)=&mut request.fields[2] else {panic!()};policy.fields[0]=NdfValue::List(vec![]);}
  if mode==1 {let NdfValue::Variant(slot)=&mut request.fields[1] else {panic!()};slot.variant="Phrasing".into();}
  if mode==2 {let NdfValue::Record(fragment)=&mut request.fields[0] else {panic!()};fragment.fields[0]=NdfValue::U64(u64::MAX);}
  assert!(transfer(&changed,&r).is_err());
 }
}
#[test]
fn ruby_bad_rp_child_from_schema_valid_first_cbor_receiver(){
 use HtmlTag::*;let r=registry();
 let q=req(vec![e(Ruby,vec![1,2,3,4],vec![]),t("字"),e(Rp,vec![5],vec![]),e(Rt,vec![6],vec![]),e(Rp,vec![7],vec![]),t("("),t("じ"),t(")")]);
 let mut raw=encode(&q,&r);
 // Replace the valid text node '(' by an Em node pointing at a new text node.
 // Every field remains schema-valid; only the HTML content model is broken.
 let NdfValue::Record(request)=&mut raw else {panic!()};let NdfValue::Record(fragment)=&mut request.fields[0] else {panic!()};let NdfValue::List(nodes)=&mut fragment.fields[1] else {panic!()};
 let saved=nodes[5].clone();let mut inserted=nodes[2].clone();let NdfValue::Variant(element)=&mut inserted else {panic!()};let NdfValue::Variant(tag)=&mut element.fields[0] else {panic!()};tag.variant="Em".into();element.fields[2]=NdfValue::List(vec![NdfValue::U64(8)]);nodes[5]=inserted;nodes.push(saved);
 let result=transfer(&raw,&r);println!("RP_FIRST_RECEIVER accepted={}",result.is_ok());
 if let Ok(received)=result {let s=serialize(&validate(&received.fragment,received.slot,&received.policy,&mut b()).unwrap(),&mut b()).unwrap();println!("RP_FIRST_RECEIVER {s}");}
}

